    def __init__(self):
        super().__init__()
        self.reset_registers()

    def reset_registers(self):
        self.regs = {
            0x00: 0x0000,  # TEMP: 9-bit default resolution, reset to 0°C
            0x01: 0x0080,  # CONFIG: Default 9-bit resolution, read back 0x80 after power-up or reset
            0x02: 0x4B00,  # TLOW: 9-bit threshold for low temperature, reset to 75°C
            0x03: 0x5000,  # THIGH: 9-bit threshold for high temperature, reset to 80°C
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr}")
        value = self.regs[addr]
        if nbytes == 1:
            return value >> 8  # Return only bits 15:8
        return value

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr}")
        if addr == 0x00 and nbytes == 1:
            return  # TEMP: Write to only bits 15:7
        if addr == 0x01 and nbytes == 1:
            if data & 0x80:  # Check if OS/ALERT bit is set
                self.regs[addr] |= 0x80  # Set OS/ALERT to 1
            else:
                self.regs[addr] &= ~0x80  # Clear OS/ALERT to 0
        self.regs[addr] = data

